420	     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
421	     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
422	     * e.g. {@code http://}.
423	     *
424	     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
425	     * @return this Safelist, for chaining.
426	     * @see #addProtocols
427	     */
428	    public Safelist preserveRelativeLinks(boolean preserve) {
429	        preserveRelativeLinks = preserve;
430	        return this;
431	    }
432	
433	    /**
434	     * Get the current setting for preserving relative links.
435	     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
436	     */
437	    public boolean preserveRelativeLinks() {
438	        return preserveRelativeLinks;
439	    }
440	
441	    /**
442	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
443	     URLs with the defined protocol.
444	     <p>
445	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
446	     </p>
447	     <p>
448	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
449	     E.g.: <code>addProtocols("a", "href", "#")</code>
450	     </p>
451	
452	     @param tag       Tag the URL protocol is for
453	     @param attribute       Attribute name
454	     @param protocols List of valid protocols
455	     @return this, for chaining
456	     */
457	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
458	        Validate.notEmpty(tag);
459	        Validate.notEmpty(attribute);
460	        Validate.notNull(protocols);
461	
462	        TagName tagName = TagName.valueOf(tag);
463	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
464	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
465	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
466	
467	        for (String protocol : protocols) {
468	            Validate.notEmpty(protocol);
469	            Protocol prot = Protocol.valueOf(protocol);
470	            protSet.add(prot);
471	        }
472	        return this;
473	    }
474	
475	    /**
476	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
477	     attribute will allow any protocol.
478	     <p>
479	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
480	     </p>
481	
482	     @param tag Tag the URL protocol is for
483	     @param attribute Attribute name
484	     @param removeProtocols List of invalid protocols
485	     @return this, for chaining
486	     */
487	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
488	        Validate.notEmpty(tag);
489	        Validate.notEmpty(attribute);
490	        Validate.notNull(removeProtocols);
491	
492	        TagName tagName = TagName.valueOf(tag);
493	        AttributeKey attr = AttributeKey.valueOf(attribute);
494	
495	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
496	        // be surprising
497	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
498	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
499	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
500	
501	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
502	        for (String protocol : removeProtocols) {
503	            Validate.notEmpty(protocol);
504	            attrProtocols.remove(Protocol.valueOf(protocol));
505	        }
506	
507	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
508	            tagProtocols.remove(attr);
509	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
510	                protocols.remove(tagName);
511	        }
512	        return this;
513	    }
514	
515	    /**
516	     * Test if the supplied tag is allowed by this safelist.
517	     * @param tag test tag
518	     * @return true if allowed
519	     */
520	    public boolean isSafeTag(String tag) {
521	        return tagNames.contains(TagName.valueOf(tag));
522	    }
523	
524	    /**
525	     * Test if the supplied attribute is allowed by this safelist for this tag.
526	     * <p>This method does not modify the input element or attribute.</p>
527	     * <p>Note that for {@code srcset} attributes, which hold a comma-separated list of URL candidates, this method
528	     * only tests that the attribute itself is allowed; the {@link Cleaner} validates each candidate URL against the
529	     * configured protocols when cleaning.</p>
530	     * @param tagName tag to consider allowing the attribute in
531	     * @param el element under test, to confirm protocol
532	     * @param attr attribute under test
533	     * @return true if allowed
534	     */
535	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
536	        TagName tag = TagName.valueOf(tagName);
537	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
538	
539	        Set<AttributeKey> okSet = attributes.get(tag);
540	        if (okSet != null && okSet.contains(key)) {
541	            if (protocols.containsKey(tag)) {
542	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
543	                // ok if not defined protocol; otherwise test. srcset URLs are tested per candidate in the Cleaner.
544	                return !attrProts.containsKey(key) || isSrcset(attr.getKey())
545	                    || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
546	            } else { // attribute found, no protocols defined, so OK
547	                return true;
548	            }
549	        }
550	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
551	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
552	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
553	            // if the input already has that exact value, treat it as safe
554	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
555	        }
556	        // no attributes defined for tag, try :all tag
557	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
558	    }
559	
560	    private String getProtocolValue(Element el, Attribute attr) {
561	        String value = el.absUrl(attr.getKey());
562	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
563	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
564	        return value;
565	    }
566	
567	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
568	        for (Protocol protocol : protocols) {
569	            String prot = protocol.toString();
570	
571	            if (prot.equals("#")) { // allows anchor links
572	                if (isValidAnchor(value)) {
573	                    return true;
574	                } else {
575	                    continue;
576	                }
577	            }
578	
579	            String lc = lowerCase(value);
580	            if (lc.startsWith(prot)
581	                && lc.length() > prot.length()
582	                && lc.charAt(prot.length()) == ':') {
583	                return true;
584	            }
585	        }
586	        return false;
587	    }
588	
589	    /**
590	     Tests if the attribute is {@code srcset} (case-insensitive), which holds a comma-separated list of image
591	     candidate URLs and so gets per-candidate cleaning in the {@link Cleaner}.
592	     */
593	    static boolean isSrcset(String attrKey) {
594	        return attrKey.equalsIgnoreCase(Srcset);
595	    }
596	
597	    /**
598	     Cleans a {@code srcset} attribute value, candidate by candidate. Candidates with invalid syntax (missing URL,
599	     empty candidates, malformed descriptors, or trailing junk) are dropped, as are those whose URL fails the
600	     protocol checks configured for the attribute on this tag. Surviving candidates keep their original order and
601	     are normalized to {@code url descriptor, url descriptor} form. Does not throw on malformed input.
602	
603	     @param tagName the tag the attribute is on; selects the applicable protocol configuration
604	     @param el the element the attribute is on, to resolve URLs against its base URI
605	     @param value the source srcset attribute value
606	     @return the cleaned value, or {@code null} if no candidates survive (in which case the attribute is removed)
607	     */
608	    String cleanSrcset(String tagName, Element el, String value) {
609	        Set<Protocol> protocols = srcsetProtocols(TagName.valueOf(tagName));
610	        StringBuilder sb = StringUtil.borrowBuilder();
611	
612	        int pos = 0, length = value.length();
613	        while (pos <= length) {
614	            // find the end of this candidate: a comma separates candidates, unless it is within the URL and directly
615	            // followed by a non-whitespace, non-comma character (e.g. the comma in a data: URL). Consecutive
616	            // separators produce empty candidates, which are invalid.
617	            int start = pos, end = pos;
618	            boolean inUrl = true; // still scanning the URL run (no whitespace after URL content yet)
619	            boolean started = false; // seen non-whitespace content in this candidate
620	            while (end < length) {
621	                char c = value.charAt(end);
622	                if (c == ',') {
623	                    if (inUrl && started && end + 1 < length && !isSrcsetSpace(value.charAt(end + 1)) && value.charAt(end + 1) != ',')
624	                        end++; // comma is part of the URL
625	                    else
626	                        break; // candidate separator
627	                } else {
628	                    if (isSrcsetSpace(c)) {
629	                        if (started) inUrl = false;
630	                    } else {
631	                        started = true;
632	                    }
633	                    end++;
634	                }
635	            }
636	            appendSrcsetCandidate(el, value, start, end, protocols, sb);
637	            if (end >= length) break;
638	            pos = end + 1; // step past the separator comma
639	        }
640	
641	        if (sb.length() == 0) {
642	            StringUtil.releaseBuilderVoid(sb);
643	            return null;
644	        }
645	        return StringUtil.releaseBuilder(sb);
646	    }
647	
648	    /**
649	     Validates and appends a single srcset candidate (the {@code value} range {@code start}..{@code end}) to
650	     {@code sb}. Invalid or unsafe candidates are silently dropped; their text is never recombined into new URLs.
651	     */
652	    private void appendSrcsetCandidate(Element el, String value, int start, int end, Set<Protocol> protocols, StringBuilder sb) {
653	        // trim ASCII whitespace from the candidate
654	        while (start < end && isSrcsetSpace(value.charAt(start))) start++;
655	        while (end > start && isSrcsetSpace(value.charAt(end - 1))) end--;
656	        if (start == end) return; // empty candidate (e.g. from consecutive separators)
657	
658	        // the URL is the leading run of non-whitespace
659	        int urlEnd = start;
660	        while (urlEnd < end && !isSrcsetSpace(value.charAt(urlEnd))) urlEnd++;
661	        String url = value.substring(start, urlEnd);
662	
663	        // an optional descriptor may follow, introduced by at least one ASCII space
664	        String descriptor = null;
665	        if (urlEnd < end) {
666	            if (value.charAt(urlEnd) != ' ') return; // the descriptor must be space-separated from the URL
667	            int descStart = urlEnd;
668	            while (descStart < end && value.charAt(descStart) == ' ') descStart++;
669	            int descEnd = descStart;
670	            while (descEnd < end && !isSrcsetSpace(value.charAt(descEnd))) descEnd++;
671	            if (descEnd != end) return; // unexpected content after the descriptor (e.g. a second descriptor)
672	            descriptor = value.substring(descStart, descEnd);
673	            if (!isValidSrcsetDescriptor(descriptor)) return;
674	        }
675	
676	        if (protocols != null && !isSafeSrcsetUrl(el, url, protocols)) return;
677	
678	        if (sb.length() > 0) sb.append(", ");
679	        sb.append(url);
680	        if (descriptor != null) sb.append(' ').append(descriptor);
681	    }
682	
683	    /**
684	     Finds the protocol configuration applicable to {@code srcset} on the given tag, following the same tag to
685	     {@code :all} fallback as {@link #isSafeAttribute}, so that per-tag differences neither widen nor narrow each
686	     other. Returns {@code null} when URLs are unrestricted.
687	     */
688	    private Set<Protocol> srcsetProtocols(TagName tag) {
689	        Set<AttributeKey> okSet = attributes.get(tag);
690	        if (okSet != null && okSet.contains(SrcsetKey)) {
691	            Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
692	            return attrProts != null ? attrProts.get(SrcsetKey) : null;
693	        }
694	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
695	        if (enforcedSet != null && enforcedSet.containsKey(SrcsetKey)) return null;
696	        return !tag.equals(AllTag) ? srcsetProtocols(AllTag) : null;
697	    }
698	
699	    private boolean isSafeSrcsetUrl(Element el, String url, Set<Protocol> protocols) {
700	        String value = StringUtil.resolve(el.baseUri(), url);
701	        if (value.isEmpty() && !StringUtil.hasHttpScheme(url))
702	            value = url; // if it could not be made absolute, run as-is to allow custom unknown protocols
703	        return isSafeProtocol(value, protocols);
704	    }
705	
706	    /**
707	     Validates a srcset descriptor: a positive integer followed by a lowercase {@code w} (e.g. {@code 100w}), or a
708	     positive number (digits, or digits.digits) followed by a lowercase {@code x} (e.g. {@code 2x}, {@code 1.5x}).
709	     Signs, exponents, a dot missing a side, and zero values are all invalid.
710	     */
711	    private static boolean isValidSrcsetDescriptor(String descriptor) {
712	        int length = descriptor.length();
713	        if (length < 2) return false;
714	        String number = descriptor.substring(0, length - 1);
715	        switch (descriptor.charAt(length - 1)) {
716	            case 'w': return isPositiveInteger(number);
717	            case 'x': return isPositiveNumber(number);
718	            default:  return false;
719	        }
720	    }
721	
722	    /** Tests if the value is all digits and greater than zero. */
723	    private static boolean isPositiveInteger(String number) {
724	        boolean nonZero = false;
725	        for (int i = 0, length = number.length(); i < length; i++) {
726	            char c = number.charAt(i);
727	            if (c < '0' || c > '9') return false;
728	            if (c != '0') nonZero = true;
729	        }
730	        return nonZero;
731	    }
732	
733	    /** Tests if the value is digits, or digits.digits, and greater than zero. */
734	    private static boolean isPositiveNumber(String number) {
735	        int dot = number.indexOf('.');
736	        if (dot == -1) return isPositiveInteger(number);
737	        if (number.indexOf('.', dot + 1) != -1) return false; // at most one dot
738	        String integer = number.substring(0, dot);
739	        String fraction = number.substring(dot + 1);
740	        if (!isDigits(integer) || !isDigits(fraction)) return false; // the dot needs digits on both sides
741	        return isPositiveInteger(integer) || isPositiveInteger(fraction);
742	    }
743	
744	    private static boolean isDigits(String value) {
745	        for (int i = 0, length = value.length(); i < length; i++) {
746	            char c = value.charAt(i);
747	            if (c < '0' || c > '9') return false;
748	        }
749	        return value.length() > 0;
750	    }
751	
752	    /** The ASCII whitespace characters: space, tab, newline, carriage return, and form feed. */
753	    private static boolean isSrcsetSpace(char c) {
754	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
755	    }
756	
757	    /**
758	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
759	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
760	     attribute.
761	     */
762	    boolean shouldAbsUrl(String tagName, String attrKey) {
763	        if (preserveRelativeLinks) return false;
764	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
765	    }
766	
767	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
768	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
769	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
770	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
771	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
772	        }
773	
774	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
775	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
776	
777	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
778	    }
779	
780	    private static boolean isValidAnchor(String value) {
781	        return value.startsWith("#") && !value.matches(".*\\s.*");
782	    }
783	
784	    /**
785	     Gets the Attributes that should be enforced for a given tag
786	     * @param tagName the tag
787	     * @return the attributes that will be enforced; empty if none are set for the given tag
788	     */
789	    public Attributes getEnforcedAttributes(String tagName) {
790	        Attributes attrs = new Attributes();
791	        TagName tag = TagName.valueOf(tagName);
792	        if (enforcedAttributes.containsKey(tag)) {
793	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
794	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
795	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
796	            }
797	        }
798	        return attrs;
799	    }
800	    
801	    // named types for config. All just hold strings, but here for my sanity.
802	
803	    static class TagName extends TypedValue {
804	        TagName(String value) {
805	            super(value);
806	        }
807	
808	        static TagName valueOf(String value) {
809	            return new TagName(Normalizer.lowerCase(value));
810	        }
811	    }
812	
813	    static class AttributeKey extends TypedValue {
814	        AttributeKey(String value) {
815	            super(value);
816	        }
817	
818	        static AttributeKey valueOf(String value) {
819	            return new AttributeKey(Normalizer.lowerCase(value));
820	        }
821	    }
822	
823	    static class AttributeValue extends TypedValue {
824	        AttributeValue(String value) {
825	            super(value);
826	        }
827	
828	        static AttributeValue valueOf(String value) {
829	            return new AttributeValue(value);
830	        }
831	    }
832	
833	    static class Protocol extends TypedValue {
834	        Protocol(String value) {
835	            super(value);
836	        }
837	
838	        static Protocol valueOf(String value) {
839	            return new Protocol(value);
840	        }
841	    }
842	
843	    abstract static class TypedValue {
844	        private final String value;
845	
846	        TypedValue(String value) {
847	            Validate.notNull(value);
848	            this.value = value;
849	        }
850	
851	        @Override
852	        public int hashCode() {
853	            return value.hashCode();
854	        }
855	
856	        @Override
857	        public boolean equals(Object obj) {
858	            if (this == obj) return true;
859	            if (obj == null || getClass() != obj.getClass()) return false;
860	            TypedValue other = (TypedValue) obj;
861	            return Objects.equals(value, other.value);
862	        }
863	
864	        @Override
865	        public String toString() {
866	            return value;
867	        }
868	    }
869	}
