233	    @Test void configuredCleanerMayBeSharedAcrossThreads() throws InterruptedException {
234	        // https://github.com/jhy/jsoup/issues/2473
235	        String html = "<a href='/foo'>Link</a><img src='/bar' alt='Q'>";
236	        String baseUri = "https://example.com/";
237	        String expected = "<a href=\"https://example.com/foo\">Link</a><img src=\"https://example.com/bar\" alt=\"Q\">";
238	        Cleaner cleaner = new Cleaner(Safelist.basicWithImages());
239	
240	        int numThreads = 10;
241	        int numLoops = 20;
242	        String[] cleaned = new String[numThreads * numLoops];
243	        AtomicInteger next = new AtomicInteger();
244	        AtomicReference<Throwable> failure = new AtomicReference<>();
245	        CountDownLatch start = new CountDownLatch(1);
246	        CountDownLatch done = new CountDownLatch(numThreads);
247	        Thread[] threads = new Thread[numThreads];
248	
249	        for (int i = 0; i < numThreads; i++) {
250	            Thread thread = new Thread(() -> {
251	                try {
252	                    start.await();
253	                    for (int j = 0; j < numLoops; j++) {
254	                        Document dirty = Jsoup.parseBodyFragment(html, baseUri);
255	                        cleaned[next.getAndIncrement()] = cleaner.clean(dirty).body().html();
256	                    }
257	                } catch (Throwable t) {
258	                    failure.compareAndSet(null, t);
259	                    if (t instanceof InterruptedException) Thread.currentThread().interrupt();
260	                } finally {
261	                    done.countDown();
262	                }
263	            });
264	            threads[i] = thread;
265	            thread.start();
266	        }
267	
268	        start.countDown();
269	        done.await();
270	
271	        if (failure.get() != null)
272	            throw new AssertionError("Concurrent cleaner use failed", failure.get());
273	
274	        assertEquals(cleaned.length, next.get());
275	        for (String clean : cleaned) {
276	            assertEquals(expected, clean);
277	        }
278	    }
