import org.jsoup.Jsoup;
import org.jsoup.safety.*;

public class Probe {
    static void t(String html, Safelist sl) {
        String clean;
        try { clean = Jsoup.clean(html, sl); } catch (Exception e) { clean = "THROW:" + e; }
        boolean valid;
        try { valid = Cleaner.isValid(html, sl); } catch (Exception e) { valid = false; clean += " ISVALID-THROW:" + e; }
        // reclean to compare
        System.out.printf("%-60s valid=%-5s clean=%s%n", html.replace("\t","\\t").replace("\n","\\n"), valid, clean);
    }
    public static void main(String[] a) {
        Safelist basic = Safelist.basic();
        Safelist preserve = Safelist.basic().preserveRelativeLinks(true);
        t("<a href='http://exa mple.com/'>x</a>", basic);
        t("<a href='http://exa mple.com/'>x</a>", preserve);
        t("<a href=\"ht\ttp://example.com/\">x</a>", basic);
        t("<a href=\"ht\ttp://example.com/\">x</a>", preserve);
        t("<a href='http:'>x</a>", basic);
        t("<a href='http:'>x</a>", preserve);
        t("<a href='http://'>x</a>", basic);
        t("<a href=''>x</a>", basic);
        t("<a href='  '>x</a>", basic);
        t("<a href='  '>x</a>", preserve);
        t("<a href='HTTP://example.com/'>x</a>", basic);
        t("<a href='//example.com/'>x</a>", preserve);
        t("<a href='//example.com/'>x</a>", basic);
        t("<a href='#frag'>x</a>", preserve);
        t("<a href='?q=1'>x</a>", preserve);
        t("<a href='mailto:foo@example.com'>x</a>", basic);
        t("<a href='cid:12345'>x</a>", Safelist.basic().addProtocols("a","href","cid"));
