import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Parser;

public class Probe2 {
    static String esc(String s) {
        StringBuilder b = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c < 0x20 || c > 0x7e) b.append(String.format("\\u%04x", (int) c));
            else b.append(c);
        }
        return b.toString();
    }
    public static void main(String[] args) {
        Document d = Jsoup.parse("<a href=\"x&#0;y&#xD800;z\" title='&#55296;'>&#0;&#xDFFF;</a>");
        System.out.println("href=" + esc(d.select("a").attr("href")));
        System.out.println("title=" + esc(d.select("a").attr("title")));
        System.out.println("text=" + esc(d.body().text()));
        System.out.println(esc(Parser.unescapeEntities("&#0;&#xD800;&#65;", false)));
        System.out.println(esc(Parser.unescapeEntities("&#0;&#xD800;&#65;", true)));
        // script raw
        Document s = Jsoup.parse("<html><head><script>var a='&#65;';</script></head><body></body></html>");
        System.out.println("script=" + esc(s.select("script").html()));
    }
}

